     1→import { useRef, useState, useEffect } from 'react';
     2→import { useFrame, useThree } from '@react-three/fiber';
     3→import { Mesh, Vector3, Plane } from 'three';
     4→import { Player } from '../../models/PlayerModel';
     5→import { usePlayerStore } from '../../store/playerStore';
     6→import { snapToField } from '../../utils/fieldGeometry';
     7→
     8→interface PlayerProps {
     9→  player: Player;
    10→}
    11→
    12→export function PlayerComponent({ player }: PlayerProps) {
    13→  const meshRef = useRef<Mesh>(null);
    14→  const groupRef = useRef<THREE.Group>(null);
    15→  const [hovered, setHovered] = useState(false);
    16→  const [isDragging, setIsDragging] = useState(false);
    17→
    18→  const { selectedPlayerId, selectPlayer, updatePlayerPosition, setDragging } = usePlayerStore();
    19→  const { camera, raycaster, gl } = useThree();
    20→
    21→  const isSelected = selectedPlayerId === player.id;
    22→
    23→  // Use jerseyNumber instead of number (from updated Player model)
    24→  const jerseyNumber = player.jerseyNumber;
    25→
    26→  // Handle global pointer events for dragging
    27→  useEffect(() => {
    28→    if (!isDragging) return;
    29→
    30→    const handlePointerMove = (event: PointerEvent) => {
    31→      const rect = gl.domElement.getBoundingClientRect();
    32→      const x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    33→      const y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    34→
    35→      raycaster.setFromCamera({ x, y } as any, camera);
    36→      const plane = new Plane(new Vector3(0, 1, 0), 0);
    37→      const intersection = raycaster.ray.intersectPlane(plane, new Vector3());
    38→
    39→      if (intersection) {
    40→        const [snappedX, snappedZ] = snapToField(intersection.x, intersection.z);
    41→        updatePlayerPosition(player.id, [snappedX, 0, snappedZ]);
    42→      }
    43→    };
    44→
    45→    const handlePointerUp = () => {
    46→      setIsDragging(false);
    47→      setDragging(false);
    48→    };
    49→
    50→    // Add listeners to the window to capture events even when pointer leaves player
    51→    window.addEventListener('pointermove', handlePointerMove);
    52→    window.addEventListener('pointerup', handlePointerUp);
    53→
    54→    return () => {
    55→      window.removeEventListener('pointermove', handlePointerMove);
    56→      window.removeEventListener('pointerup', handlePointerUp);
    57→    };
    58→  }, [isDragging, camera, raycaster, gl, player.id, updatePlayerPosition, setDragging]);
    59→
    60→  useFrame(() => {
    61→    // Rotate the main body group if needed
    62→    if (groupRef.current) {
    63→      groupRef.current.rotation.y = player.rotation;
    64→    }
    65→  });
    66→
    67→  const handlePointerDown = (e: any) => {
    68→    e.stopPropagation();
    69→    selectPlayer(player.id);
    70→    setIsDragging(true);
    71→    setDragging(true); // Notify store to disable camera controls
    72→  };
    73→
    74→  return (
    75→    <group
    76→      ref={groupRef}
    77→      position={player.position}
    78→      onPointerDown={handlePointerDown}
    79→      onPointerOver={() => setHovered(true)}
    80→      onPointerOut={() => setHovered(false)}
    81→    >
    82→      {/* Head */}
    83→      <mesh position={[0, 1.75, 0]} castShadow>
    84→        <sphereGeometry args={[0.22, 16, 16]} />
    85→        <meshStandardMaterial 
    86→          color={isSelected ? '#ffff00' : hovered ? '#ffffff' : player.color}
    87→          emissive={isSelected ? '#ffff00' : undefined}
    88→          emissiveIntensity={isSelected ? 0.4 : 0}
    89→        />
    90→      </mesh>
    91→
    92→      {/* Torso */}
    93→      <mesh position={[0, 1.15, 0]} castShadow>
    94→        <capsuleGeometry args={[0.24, 0.9, 6, 12]} />
    95→        <meshStandardMaterial 
    96→          color={isSelected ? '#ffff00' : hovered ? '#eeeeee' : player.color}
    97→          emissive={isSelected ? '#ffff00' : undefined}
    98→          emissiveIntensity={isSelected ? 0.4 : 0}
    99→        />
   100→      </mesh>
   101→
   102→      {/* Arms */}
   103→      <group position={[0, 1.35, 0]}>
   104→        <mesh position={[-0.32, -0.25, 0.1]} rotation={[0, 0, Math.PI / 3.5]}>
   105→          <capsuleGeometry args={[0.09, 0.65, 6, 8]} />
   106→          <meshStandardMaterial color={player.color} />
   107→        </mesh>
   108→        <mesh position={[0.32, -0.25, 0.1]} rotation={[0, 0, -Math.PI / 3.5]}>
   109→          <capsuleGeometry args={[0.09, 0.65, 6, 8]} />
   110→          <meshStandardMaterial color={player.color} />
   111→        </mesh>
   112→      </group>
   113→
   114→      {/* Legs */}
   115→      <group position={[0, 0.45, 0]}>
   116→        <mesh position={[-0.13, -0.45, 0]}>
   117→          <capsuleGeometry args={[0.12, 0.95, 6, 8]} />
   118→          <meshStandardMaterial color={player.color} />
   119→        </mesh>
   120→        <mesh position={[0.13, -0.45, 0]}>
   121→          <capsuleGeometry args={[0.12, 0.95, 6, 8]} />
   122→          <meshStandardMaterial color={player.color} />
   123→        </mesh>
   124→      </group>
   125→
   126→      {/* Jersey number label - floating above head */}
   127→      {jerseyNumber !== undefined && (
   128→        <mesh position={[0, 2.05, 0.25]}>
   129→          {/* For now using a simple plane – later replace with Text from @react-three/drei */}
   130→          <planeGeometry args={[0.45, 0.45]} />
   131→          <meshBasicMaterial color="#ffffff" />
   132→          {/* You could add a small text sprite here later */}
   133→        </mesh>
   134→      )}
   135→
   136→      {/* Selection indicator ring */}
   137→      {isSelected && (
   138→        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.02, 0]}>
   139→          <ringGeometry args={[0.55, 0.68, 32]} />
   140→          <meshStandardMaterial 
   141→            color="#ffff00" 
   142→            emissive="#ffff00" 
   143→            emissiveIntensity={0.6} 
   144→            transparent 
   145→            opacity={0.75}
   146→          />
   147→        </mesh>
   148→      )}
   149→    </group>
   150→  );
   151→}

