    42→// Common AFL field positions (modern but roughly traditional naming)
    43→export const AFL_POSITIONS = [
    44→  // Forwards (6)
    45→  "Full Forward",
    46→  "Centre Half Forward",
    47→  "Half Forward Flank", "Half Forward Flank",
    48→  "Forward Pocket", "Forward Pocket",
    49→
    50→  // Midfield (6)
    51→  "Centre",
    52→  "Ruck",
    53→  "Rover",
    54→  "Ruck Rover",
    55→  "Wing", "Wing",
    56→
    57→  // Defenders (6)
    58→  "Full Back",
    59→  "Centre Half Back",
    60→  "Half Back Flank", "Half Back Flank",
    61→  "Back Pocket", "Back Pocket",
    62→] as const;
    63→
    64→// Create a more realistic team squad (22 players — 18 primary + 4 interchange)
    65→export function createTeamPlayers(
    66→  teamId: 'team1' | 'team2',
    67→  color: string,
    68→  playerCount: number = 22
    69→): Player[] {
    70→  const players: Player[] = [];
    71→
    72→  // Use the position list and repeat/cycle if >18
    73→  const positions = AFL_POSITIONS;
    74→
    75→  for (let i = 0; i < playerCount; i++) {
    76→    const posIndex = i % positions.length;
    77→    const posName = positions[posIndex];
    78→
    79→    // Rough height ranges by position type (cm)
    80→    let heightCm: number;
    81→    if (posName.includes("Ruck") || posName.includes("Full") || posName.includes("Centre Half")) {
    82→      heightCm = 195 + Math.floor(Math.random() * 11); // 195–205 cm tall key position players
    83→    } else if (posName.includes("Flank") || posName.includes("Wing")) {
    84→      heightCm = 180 + Math.floor(Math.random() * 11); // 180–190 cm
    85→    } else {
    86→      heightCm = 175 + Math.floor(Math.random() * 16); // 175–190 cm mids/small forwards
    87→    }
    88→
    89→    players.push({
    90→      id: `${teamId}-player-${i + 1}`,
    91→      teamId,
    92→      position: [0, 0, 0],       // still placeholder — position on field later
    93→      rotation: 0,
    94→      color,
    95→      jerseyNumber: i + 1,
    96→      heightCm,
    97→      primaryPosition: posName,
    98→    });
    99→  }
   100→
   101→  return players;
   102→}
