     1→import { FIELD_CONFIG } from '../models/FieldModel';
     2→
     3→// Helper functions for field geometry calculations
     4→
     5→export function isPointInField(x: number, z: number): boolean {
     6→  const { length, width } = FIELD_CONFIG;
     7→  
     8→  // Check if point is within oval field bounds
     9→  const normalizedX = (2 * x) / length;
    10→  const normalizedZ = (2 * z) / width;
    11→  
    12→  // Ellipse equation: (x/a)^2 + (z/b)^2 <= 1
    13→  return (normalizedX * normalizedX + normalizedZ * normalizedZ) <= 1;
    14→}
    15→
    16→export function snapToField(x: number, z: number): [number, number] {
    17→  // Snap position to field boundary if outside
    18→  if (!isPointInField(x, z)) {
    19→    const { length, width } = FIELD_CONFIG;
    20→    
    21→    // Normalize coordinates
    22→    const normalizedX = (2 * x) / length;
    23→    const normalizedZ = (2 * z) / width;
    24→    
    25→    // Calculate distance from center
    26→    const distance = Math.sqrt(normalizedX * normalizedX + normalizedZ * normalizedZ);
    27→    
    28→    if (distance > 1) {
    29→      // Project onto ellipse boundary
    30→      const angle = Math.atan2(normalizedZ, normalizedX);
    31→      const snappedX = (length / 2) * Math.cos(angle);
    32→      const snappedZ = (width / 2) * Math.sin(angle);
    33→      
    34→      return [snappedX, snappedZ];
    35→    }
    36→  }
    37→  
    38→  return [x, z];
    39→}
    40→
    41→export function getFieldBounds() {
    42→  const { length, width } = FIELD_CONFIG;
    43→  return {
    44→    minX: -length / 2,
    45→    maxX: length / 2,
    46→    minZ: -width / 2,
    47→    maxZ: width / 2,
    48→  };
    49→}
