     1→import { useRef, useState } from 'react';
     2→import { useThree } from '@react-three/fiber';
     3→import { Vector3, Raycaster, Plane } from 'three';
     4→import { usePlayerStore } from '../store/playerStore';
     5→import { snapToField } from '../utils/fieldGeometry';
     6→
     7→export function usePlayerControls() {
     8→  const { camera, raycaster, gl } = useThree();
     9→  const { selectedPlayerId, updatePlayerPosition, selectPlayer } = usePlayerStore();
    10→  const [isDragging, setIsDragging] = useState(false);
    11→  const dragStartRef = useRef<Vector3 | null>(null);
    12→  
    13→  const handlePointerDown = (event: any) => {
    14→    if (event.object && event.object.userData?.playerId) {
    15→      const playerId = event.object.userData.playerId;
    16→      selectPlayer(playerId);
    17→      setIsDragging(true);
    18→      
    19→      // Calculate initial drag position
    20→      const intersection = event.intersections[0];
    21→      if (intersection) {
    22→        dragStartRef.current = intersection.point.clone();
    23→      }
    24→    }
    25→  };
    26→  
    27→  const handlePointerMove = (event: any) => {
    28→    if (isDragging && selectedPlayerId && dragStartRef.current) {
    29→      raycaster.setFromCamera(event.pointer, camera);
    30→      
    31→      // Intersect with ground plane (y = 0)
    32→      const planeNormal = new Vector3(0, 1, 0);
    33→      const planePoint = new Vector3(0, 0, 0);
    34→      const distance = raycaster.ray.intersectPlane(
    35→        new Plane(planeNormal, -planeNormal.dot(planePoint)),
    36→        dragStartRef.current
    37→      );
    38→      
    39→      if (distance) {
    40→        const [x, z] = snapToField(distance.x, distance.z);
    41→        updatePlayerPosition(selectedPlayerId, [x, 0, z]);
    42→      }
    43→    }
    44→  };
    45→  
    46→  const handlePointerUp = () => {
    47→    setIsDragging(false);
    48→    dragStartRef.current = null;
    49→  };
    50→  
    51→  return {
    52→    isDragging,
    53→    handlePointerDown,
    54→    handlePointerMove,
    55→    handlePointerUp,
    56→  };
    57→}
    58→

