     1→import { create } from 'zustand';
     2→import Dexie, { Table } from 'dexie';
     3→import { Player } from '../models/PlayerModel';
     4→
     5→interface Playbook {
     6→  id?: number;
     7→  name: string;
     8→  description?: string;
     9→  createdAt: Date;
    10→  playerPositions: Player[];
    11→  cameraPosition: [number, number, number];
    12→  cameraTarget: [number, number, number];
    13→  cameraZoom: number;
    14→  annotations?: any[]; // Will be defined when annotations are implemented
    15→}
    16→
    17→class PlaybookDatabase extends Dexie {
    18→  playbooks!: Table<Playbook>;
    19→
    20→  constructor() {
    21→    super('AFLPlaybookDB');
    22→    this.version(1).stores({
    23→      playbooks: '++id, name, createdAt',
    24→    });
    25→  }
    26→}
    27→
    28→const db = new PlaybookDatabase();
    29→
    30→interface PlaybookState {
    31→  playbooks: Playbook[];
    32→  currentPlaybook: Playbook | null;
    33→  isLoading: boolean;
    34→  
    35→  // Actions
    36→  loadPlaybooks: () => Promise<void>;
    37→  savePlaybook: (playbook: Omit<Playbook, 'id' | 'createdAt'>) => Promise<number>;
    38→  deletePlaybook: (id: number) => Promise<void>;
    39→  loadPlaybook: (id: number) => Promise<void>;
    40→  clearCurrentPlaybook: () => void;
    41→}
    42→
    43→export const usePlaybookStore = create<PlaybookState>((set) => ({
    44→  playbooks: [],
    45→  currentPlaybook: null,
    46→  isLoading: false,
    47→  
    48→  loadPlaybooks: async () => {
    49→    set({ isLoading: true });
    50→    try {
    51→      const playbooks = await db.playbooks.orderBy('createdAt').reverse().toArray();
    52→      set({ playbooks, isLoading: false });
    53→    } catch (error) {
    54→      console.error('Error loading playbooks:', error);
    55→      set({ isLoading: false });
    56→    }
    57→  },
    58→  
    59→  savePlaybook: async (playbookData) => {
    60→    try {
    61→      const playbook: Playbook = {
    62→        ...playbookData,
    63→        createdAt: new Date(),
    64→      };
    65→      const id = await db.playbooks.add(playbook);
    66→      await usePlaybookStore.getState().loadPlaybooks();
    67→      return id;
    68→    } catch (error) {
    69→      console.error('Error saving playbook:', error);
    70→      throw error;
    71→    }
    72→  },
    73→  
    74→  deletePlaybook: async (id) => {
    75→    try {
    76→      await db.playbooks.delete(id);
    77→      await usePlaybookStore.getState().loadPlaybooks();
    78→      if (usePlaybookStore.getState().currentPlaybook?.id === id) {
    79→        set({ currentPlaybook: null });
    80→      }
    81→    } catch (error) {
    82→      console.error('Error deleting playbook:', error);
    83→      throw error;
    84→    }
    85→  },
    86→  
    87→  loadPlaybook: async (id) => {
    88→    try {
    89→      const playbook = await db.playbooks.get(id);
    90→      if (playbook) {
    91→        set({ currentPlaybook: playbook });
    92→      }
    93→    } catch (error) {
    94→      console.error('Error loading playbook:', error);
    95→      throw error;
    96→    }
    97→  },
    98→  
    99→  clearCurrentPlaybook: () => {
   100→    set({ currentPlaybook: null });
   101→  },
   102→}));
