     1→import { create } from 'zustand';
     2→import { Ball, createBall } from '../models/BallModel';
     3→
     4→interface BallState {
     5→  ball: Ball | null;
     6→  isBallSelected: boolean;
     7→
     8→  // Actions
     9→  initializeBall: (position?: [number, number, number]) => void;
    10→  updateBallPosition: (position: [number, number, number]) => void;
    11→  assignBallToPlayer: (playerId: string | null) => void;
    12→  selectBall: (selected: boolean) => void;
    13→  removeBall: () => void;
    14→  resetBall: () => void;
    15→  getBall: () => Ball | null;
    16→  hasBall: () => boolean;
    17→}
    18→
    19→export const useBallStore = create<BallState>((set, get) => ({
    20→  ball: null,
    21→  isBallSelected: false,
    22→
    23→  initializeBall: (position = [0, 0.5, 0]) => {
    24→    const ball = createBall(position);
    25→    set({ ball });
    26→  },
    27→
    28→  updateBallPosition: (position) => {
    29→    set((state) => {
    30→      if (!state.ball) return state;
    31→      return {
    32→        ball: { ...state.ball, position },
    33→      };
    34→    });
    35→  },
    36→
    37→  assignBallToPlayer: (playerId) => {
    38→    set((state) => {
    39→      if (!state.ball) return state;
    40→      return {
    41→        ball: { ...state.ball, assignedPlayerId: playerId ?? undefined },
    42→      };
    43→    });
    44→  },
    45→
    46→  selectBall: (selected) => {
    47→    set({ isBallSelected: selected });
    48→  },
    49→
    50→  removeBall: () => {
    51→    set({ ball: null, isBallSelected: false });
    52→  },
    53→
    54→  resetBall: () => {
    55→    const ball = createBall([0, 0.5, 0]);
    56→    set({ ball, isBallSelected: false });
    57→  },
    58→
    59→  getBall: () => {
    60→    return get().ball;
    61→  },
    62→
    63→  hasBall: () => {
    64→    return get().ball !== null;
    65→  },
    66→}));
    67→

