     5→import { useBallStore } from '../../store/ballStore';
     6→import { usePlayerStore } from '../../store/playerStore';
     7→import { useAnimationStore } from '../../store/animationStore';
     8→import { usePathStore } from '../../store/pathStore';
     9→import { snapToField } from '../../utils/fieldGeometry';
    10→
    11→interface BallProps {
    12→  ball: Ball;
    13→}
    14→
    15→export function BallComponent({ ball }: BallProps) {
    16→  const meshRef = useRef<Mesh>(null);
    17→  const groupRef = useRef<any>(null);
    18→  const [hovered, setHovered] = useState(false);
    19→  const [isDragging, setIsDragging] = useState(false);
    20→  const { isBallSelected, selectBall, updateBallPosition } = useBallStore();
    21→  const { getPlayer } = usePlayerStore();
    22→  const { isPlaying, getPositionForPath, tick } = useAnimationStore();
    23→  const { getPathByEntity } = usePathStore();
    24→  const { camera, raycaster } = useThree();
    25→
    26→  // Get the assigned player (if ball is assigned to a player)
    27→  const assignedPlayer = ball.assignedPlayerId ? getPlayer(ball.assignedPlayerId) : undefined;
    28→
    29→  // Get the ball's movement path (if any)
    30→  const ballPath = getPathByEntity(ball.id, 'ball');
    31→
    32→  useFrame((state, delta) => {
    33→    // Priority 1: Follow assigned player (overrides path animation)
    34→    if (assignedPlayer && !isDragging) {
    35→      // Position ball at player's position with slight Y offset to appear "held"
    36→      if (groupRef.current) {
    37→        groupRef.current.position.set(
    38→          assignedPlayer.position[0],
    39→          assignedPlayer.position[1] + ball.size + 0.5, // Position above player
    40→          assignedPlayer.position[2]
    41→        );
    42→      }
    43→    }
    44→    // Priority 2: Handle animation playback - update ball position along path
    45→    else if (isPlaying && ballPath && !isDragging) {
    46→      // Advance animation progress
    47→      tick(delta);
    48→
    49→      // Get interpolated position from path at current progress
    50→      const animatedPosition = getPositionForPath(ballPath, true);
    51→
    52→      // Update group position directly for smooth 60fps rendering
    53→      if (groupRef.current) {
    54→        groupRef.current.position.set(
    55→          animatedPosition[0],
    56→          animatedPosition[1],
    57→          animatedPosition[2]
    58→        );
    59→      }
    60→    }
    61→
    62→    // Handle dragging with global pointer events
    63→    if (isDragging) {
    64→      raycaster.setFromCamera(state.pointer, camera);
    65→      const planeNormal = new Vector3(0, 1, 0);
    66→      const planePoint = new Vector3(0, 0, 0);
    67→      const intersection = raycaster.ray.intersectPlane(
    68→        new Plane(planeNormal, -planeNormal.dot(planePoint)),
    69→        new Vector3()
    70→      );
    71→
    72→      if (intersection) {
    73→        const [x, z] = snapToField(intersection.x, intersection.z);
    74→        updateBallPosition([x, ball.size, z]);
    75→      }
    76→    }
    77→  });
    78→
    79→  const handleClick = (e: any) => {
    80→    e.stopPropagation();
    81→    selectBall(true);
    82→  };
    83→
    84→  const handlePointerDown = (e: any) => {
    85→    e.stopPropagation();
    86→    selectBall(true);
    87→    setIsDragging(true);
    88→  };
    89→
    90→  const handlePointerMove = (e: any) => {
    91→    // Movement is handled in useFrame for smoother dragging
    92→    if (isDragging) {
    93→      e.stopPropagation();
    94→    }
    95→  };
    96→
    97→  const handlePointerUp = (e: any) => {
    98→    e.stopPropagation();
    99→    setIsDragging(false);
   100→  };
   101→
   102→  return (
   103→    <group
   104→      ref={groupRef}
   105→      position={ball.position}
   106→      onClick={handleClick}
   107→      onPointerDown={handlePointerDown}
   108→      onPointerMove={handlePointerMove}
   109→      onPointerUp={handlePointerUp}
   110→      onPointerOver={() => setHovered(true)}
   111→      onPointerOut={() => {
   112→        setHovered(false);
   113→        setIsDragging(false);
   114→      }}
   115→    >
   116→      {/* Ball mesh - sphere shape */}
   117→      <mesh ref={meshRef} castShadow>
   118→        <sphereGeometry args={[ball.size, 16, 16]} />
   119→        <meshStandardMaterial
   120→          color={isBallSelected ? '#ffff00' : hovered ? '#CD853F' : ball.color}
   121→          emissive={isBallSelected ? '#ffff00' : ball.color}
   122→          emissiveIntensity={isBallSelected ? 0.3 : 0.15}
   123→          roughness={0.6}
   124→          metalness={0.1}
   125→        />
   126→      </mesh>
   127→
   128→      {/* Selection indicator ring */}
   129→      {isBallSelected && (
   130→        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -ball.size + 0.01, 0]}>
   131→          <ringGeometry args={[ball.size + 0.1, ball.size + 0.2, 16]} />
   132→          <meshStandardMaterial color="#ffff00" emissive="#ffff00" emissiveIntensity={0.5} />
   133→        </mesh>
   134→      )}
   135→    </group>
   136→  );
   137→}
