     1→import { create } from 'zustand';
     2→import { MovementPath } from '../models/PathModel';
     3→import { getPositionAtProgress, getPositionAtProgressWithEasing, easeInOut } from '../utils/pathAnimation';
     4→
     5→interface AnimationState {
     6→  // Playback state
     7→  isPlaying: boolean;
     8→  progress: number; // 0 to 1
     9→  speed: number; // Playback speed multiplier (1.0 = normal)
    10→  duration: number; // Total animation duration in seconds
    11→
    12→  // Actions - Playback controls
    13→  play: () => void;
    14→  pause: () => void;
    15→  stop: () => void;
    16→  togglePlay: () => void;
    17→  setProgress: (progress: number) => void;
    18→  setSpeed: (speed: number) => void;
    19→  setDuration: (duration: number) => void;
    20→
    21→  // Actions - Animation frame update
    22→  tick: (deltaTime: number) => void;
    23→
    24→  // Getters - Path interpolation
    25→  getPositionForPath: (path: MovementPath, useEasing?: boolean) => [number, number, number];
    26→  getProgress: () => number;
    27→  isAnimating: () => boolean;
    28→}
    29→
    30→// Animation defaults
    31→const ANIMATION_DEFAULTS = {
    32→  speed: 1.0,
    33→  duration: 5.0, // 5 second default animation
    34→  minSpeed: 0.1,
    35→  maxSpeed: 5.0,
    36→} as const;
    37→
    38→export const useAnimationStore = create<AnimationState>((set, get) => ({
    39→  isPlaying: false,
    40→  progress: 0,
    41→  speed: ANIMATION_DEFAULTS.speed,
    42→  duration: ANIMATION_DEFAULTS.duration,
    43→
    44→  // Playback controls
    45→  play: () => {
    46→    set({ isPlaying: true });
    47→  },
    48→
    49→  pause: () => {
    50→    set({ isPlaying: false });
    51→  },
    52→
    53→  stop: () => {
    54→    set({ isPlaying: false, progress: 0 });
    55→  },
    56→
    57→  togglePlay: () => {
    58→    set((state) => ({ isPlaying: !state.isPlaying }));
    59→  },
    60→
    61→  setProgress: (progress) => {
    62→    // Clamp progress between 0 and 1
    63→    const clampedProgress = Math.max(0, Math.min(1, progress));
    64→    set({ progress: clampedProgress });
    65→  },
    66→
    67→  setSpeed: (speed) => {
    68→    // Clamp speed to valid range
    69→    const clampedSpeed = Math.max(
    70→      ANIMATION_DEFAULTS.minSpeed,
    71→      Math.min(ANIMATION_DEFAULTS.maxSpeed, speed)
    72→    );
    73→    set({ speed: clampedSpeed });
    74→  },
    75→
    76→  setDuration: (duration) => {
    77→    // Ensure positive duration
    78→    const validDuration = Math.max(0.1, duration);
    79→    set({ duration: validDuration });
    80→  },
    81→
    82→  // Animation frame update - called each frame during playback
    83→  tick: (deltaTime) => {
    84→    const state = get();
    85→    if (!state.isPlaying) return;
    86→
    87→    // Calculate progress increment based on delta time, speed, and duration
    88→    const progressIncrement = (deltaTime * state.speed) / state.duration;
    89→    const newProgress = state.progress + progressIncrement;
    90→
    91→    if (newProgress >= 1) {
    92→      // Animation complete - stop at end
    93→      set({ progress: 1, isPlaying: false });
    94→    } else {
    95→      set({ progress: newProgress });
    96→    }
    97→  },
    98→
    99→  // Get interpolated position for a path at current progress
   100→  getPositionForPath: (path, useEasing = true) => {
   101→    const { progress } = get();
   102→
   103→    if (useEasing) {
   104→      return getPositionAtProgressWithEasing(path, progress, easeInOut);
   105→    }
   106→    return getPositionAtProgress(path, progress);
   107→  },
   108→
   109→  // Getters
   110→  getProgress: () => {
   111→    return get().progress;
   112→  },
   113→
   114→  isAnimating: () => {
   115→    return get().isPlaying;
   116→  },
   117→}));
