     1→import { useMemo } from 'react';
     2→import { MovementPath } from '../../models/PathModel';
     3→import { samplePathPositions, pathHasMovement } from '../../utils/pathAnimation';
     4→
     5→/**
     6→ * Path component - Visualizes entity movement paths on the 3D field
     7→ * Renders path line and keyframe waypoints using Three.js line primitives
     8→ */
     9→
    10→// Configuration for path rendering
    11→const PATH_CONFIG = {
    12→  lineHeight: 0.05, // Height above field surface
    13→  lineSegments: 32, // Number of segments for smooth path rendering
    14→  waypointRadius: 0.4, // Radius of keyframe waypoint markers
    15→  colors: {
    16→    ball: '#ff6b00', // Orange for ball paths
    17→    player: '#00bfff', // Blue for player paths
    18→    selected: '#ffff00', // Yellow for selected paths
    19→    waypoint: '#ffffff', // White for waypoint markers
    20→  },
    21→} as const;
    22→
    23→interface PathProps {
    24→  path: MovementPath;
    25→  selected?: boolean;
    26→  showWaypoints?: boolean;
    27→  color?: string;
    28→}
    29→
    30→/**
    31→ * Main Path component for rendering movement paths
    32→ */
    33→export function Path({
    34→  path,
    35→  selected = false,
    36→  showWaypoints = true,
    37→  color,
    38→}: PathProps) {
    39→  // Don't render if path has no movement
    40→  if (!pathHasMovement(path)) {
    41→    return null;
    42→  }
    43→
    44→  // Determine path color based on entity type and selection state
    45→  const pathColor = useMemo(() => {
    46→    if (selected) return PATH_CONFIG.colors.selected;
    47→    if (color) return color;
    48→    return path.entityType === 'ball'
    49→      ? PATH_CONFIG.colors.ball
    50→      : PATH_CONFIG.colors.player;
    51→  }, [selected, color, path.entityType]);
    52→
    53→  // Sample positions along the path for smooth rendering
    54→  const pathPoints = useMemo(() => {
    55→    const positions = samplePathPositions(path, PATH_CONFIG.lineSegments);
    56→    // Flatten positions into array for bufferAttribute
    57→    const points: number[] = [];
    58→    positions.forEach((pos) => {
    59→      points.push(pos[0], PATH_CONFIG.lineHeight, pos[2]); // x, y (height), z
    60→    });
    61→    return new Float32Array(points);
    62→  }, [path]);
    63→
    64→  return (
    65→    <group>
    66→      {/* Path line rendering */}
    67→      <PathLine points={pathPoints} color={pathColor} />
    68→
    69→      {/* Keyframe waypoint markers */}
    70→      {showWaypoints && (
    71→        <PathWaypoints
    72→          keyframes={path.keyframes}
    73→          selected={selected}
    74→        />
    75→      )}
    76→    </group>
    77→  );
    78→}
    79→
    80→interface PathLineProps {
    81→  points: Float32Array;
    82→  color: string;
    83→}
    84→
    85→/**
    86→ * PathLine - Renders the continuous line path between keyframes
    87→ */
    88→function PathLine({ points, color }: PathLineProps) {
    89→  // Render as multiple connected line segments (same pattern as Field.tsx)
    90→  const segments = useMemo(() => {
    91→    const result: Array<{ start: [number, number, number]; end: [number, number, number] }> = [];
    92→    const numPoints = points.length / 3;
    93→
    94→    for (let i = 0; i < numPoints - 1; i++) {
    95→      const startIdx = i * 3;
    96→      const endIdx = (i + 1) * 3;
    97→      result.push({
    98→        start: [points[startIdx], points[startIdx + 1], points[startIdx + 2]],
    99→        end: [points[endIdx], points[endIdx + 1], points[endIdx + 2]],
   100→      });
   101→    }
   102→
   103→    return result;
   104→  }, [points]);
   105→
   106→  return (
   107→    <group>
   108→      {segments.map((segment, index) => (
   109→        <line key={`path-segment-${index}`}>
   110→          <bufferGeometry>
   111→            <bufferAttribute
   112→              attach="attributes-position"
   113→              count={2}
   114→              array={new Float32Array([
   115→                segment.start[0], segment.start[1], segment.start[2],
   116→                segment.end[0], segment.end[1], segment.end[2],
   117→              ])}
   118→              itemSize={3}
   119→            />
   120→          </bufferGeometry>
   121→          <lineBasicMaterial color={color} linewidth={2} />
   122→        </line>
   123→      ))}
   124→    </group>
   125→  );
   126→}
   127→
   128→interface PathWaypointsProps {
   129→  keyframes: MovementPath['keyframes'];
   130→  selected: boolean;
   131→}
   132→
   133→/**
   134→ * PathWaypoints - Renders markers at each keyframe position
   135→ */
   136→function PathWaypoints({ keyframes, selected }: PathWaypointsProps) {
   137→  return (
   138→    <group>
   139→      {keyframes.map((keyframe, index) => (
   140→        <WaypointMarker
   141→          key={`waypoint-${index}`}
   142→          position={keyframe.position}
   143→          isFirst={index === 0}
   144→          isLast={index === keyframes.length - 1}
   145→          selected={selected}
   146→        />
   147→      ))}
   148→    </group>
   149→  );
   150→}
   151→
   152→interface WaypointMarkerProps {
   153→  position: [number, number, number];
   154→  isFirst: boolean;
   155→  isLast: boolean;
   156→  selected: boolean;
   157→}
   158→
   159→/**
   160→ * WaypointMarker - Visual marker for individual keyframe waypoints
   161→ */
   162→function WaypointMarker({ position, isFirst, isLast, selected }: WaypointMarkerProps) {
   163→  // Determine marker color based on position in path
   164→  const markerColor = useMemo(() => {
   165→    if (selected) return PATH_CONFIG.colors.selected;
   166→    if (isFirst) return '#00ff00'; // Green for start
   167→    if (isLast) return '#ff0000'; // Red for end
   168→    return PATH_CONFIG.colors.waypoint;
   169→  }, [selected, isFirst, isLast]);
   170→
   171→  // Slightly larger markers for start/end
   172→  const radius = (isFirst || isLast)
   173→    ? PATH_CONFIG.waypointRadius * 1.2
   174→    : PATH_CONFIG.waypointRadius;
   175→
   176→  return (
   177→    <mesh
   178→      position={[position[0], PATH_CONFIG.lineHeight + 0.01, position[2]]}
   179→      rotation={[-Math.PI / 2, 0, 0]}
   180→    >
   181→      <circleGeometry args={[radius, 16]} />
   182→      <meshBasicMaterial color={markerColor} />
   183→    </mesh>
   184→  );
   185→}
   186→
   187→/**
   188→ * PathArrowhead - Arrow indicator showing direction of movement
   189→ * Can be used to show travel direction at path end
   190→ */
   191→interface PathArrowheadProps {
   192→  position: [number, number, number];
   193→  direction: [number, number, number];
   194→  color: string;
   195→}
   196→
   197→export function PathArrowhead({ position, direction, color }: PathArrowheadProps) {
   198→  // Calculate rotation from direction vector
   199→  const rotation = useMemo(() => {
   200→    const angle = Math.atan2(direction[2], direction[0]);
   201→    return [0, -angle, 0] as [number, number, number];
   202→  }, [direction]);
   203→
   204→  return (
   205→    <mesh
   206→      position={[position[0], PATH_CONFIG.lineHeight + 0.02, position[2]]}
   207→      rotation={rotation}
   208→    >
   209→      <coneGeometry args={[0.3, 0.6, 8]} />
   210→      <meshBasicMaterial color={color} />
   211→    </mesh>
   212→  );
   213→}
   214→
   215→/**
   216→ * PathManager - Component to render all paths from pathStore
   217→ * Use this in the scene to render all entity paths
   218→ */
   219→interface PathManagerProps {
   220→  paths: MovementPath[];
   221→  selectedPathId?: string | null;
   222→  showWaypoints?: boolean;
   223→}
   224→
   225→export function PathManager({
   226→  paths,
   227→  selectedPathId,
   228→  showWaypoints = true,
   229→}: PathManagerProps) {
   230→  return (
   231→    <group>
   232→      {paths.map((path) => (
   233→        <Path
   234→          key={path.id}
   235→          path={path}
   236→          selected={path.id === selectedPathId}
   237→          showWaypoints={showWaypoints}
   238→        />
   239→      ))}
   240→    </group>
   241→  );
   242→}
   243→
   244→export default Path;
